use pulldown_cmark::*;
fn ex(path:&str)->Vec<String>{ let t=std::fs::read_to_string(path).unwrap(); let mut v=vec![]; let mut cur:Option<String>=None; let mut in_md=false;
 for l in t.lines(){ if l.starts_with("````````````````````````````````"){ if l.contains("example"){cur=Some(String::new());in_md=true;} else { if let Some(c)=cur.take(){v.push(c);} in_md=false; } continue;} if cur.is_some()&&in_md{ if l=="."{in_md=false;} else { let c=cur.as_mut().unwrap(); c.push_str(&l.replace('→',"\t")); c.push('\n'); } } } v }
fn h(s:&str,o:Options)->String{let mut h=String::new(); html::push_html(&mut h,Parser::new_ext(s,o)); h}
fn squash(s:&str)->String{ s.replace("<p>","").replace("</p>","").replace('\n',"") }
fn main(){ let b="/work/crate/pulldown-cmark/third_party/CommonMark/spec.txt"; let exs=ex(b);
 let flips:[(&str,Options,&[&str]);14]=[("tables",Options::ENABLE_TABLES,&["|"]),("footnotes",Options::ENABLE_FOOTNOTES,&["[^"]),("oldfn",Options::ENABLE_OLD_FOOTNOTES,&["[^"]),("strike",Options::ENABLE_STRIKETHROUGH,&["~"]),("tasks",Options::ENABLE_TASKLISTS,&["[ ]","[x]","[X]"]),("smart",Options::ENABLE_SMART_PUNCTUATION,&["'","\"","--","..."]),("hattrs",Options::ENABLE_HEADING_ATTRIBUTES,&["{"]),("yaml",Options::ENABLE_YAML_STYLE_METADATA_BLOCKS,&["---"]),("plus",Options::ENABLE_PLUSES_DELIMITED_METADATA_BLOCKS,&["+++"]),("math",Options::ENABLE_MATH,&["$"]),("gfm",Options::ENABLE_GFM,&["[!"]),("dl",Options::ENABLE_DEFINITION_LIST,&[":"]),("sup",Options::ENABLE_SUPERSCRIPT,&["^"]),("wiki",Options::ENABLE_WIKILINKS,&["[["])];
 for (n,o,tr) in flips.iter(){ let mut cnt=0; let mut tcnt=0; let mut shown=0; for m in &exs{ let a=h(m,Options::empty()); let x=h(m,*o); if a!=x { let trig=tr.iter().any(|t|m.contains(t)); if trig {tcnt+=1; if std::env::args().nth(1).as_deref()==Some(*n)&&shown<30{shown+=1;println!("  T IN {m:?}\n    {a:?}\n    {x:?}");} } else {cnt+=1; println!("  NOTRIG {n} IN {m:?}\n    {a:?}\n    {x:?}");} } } println!("{n}: no-trigger diffs={cnt} trigger diffs={tcnt}"); }
 // footnote / definition wrapping
 let fo=Options::ENABLE_FOOTNOTES; let mut f=0; for m in &exs{ if m.contains('\t')||m.starts_with(' ')||m.contains("[^"){continue;} let mut first=true; let inp:String=m.split_inclusive('\n').map(|l|{ if first{first=false;format!("[^z]: {l}")} else if l=="\n"{l.to_string()} else {format!("    {l}")}}).collect(); let base=h(m,fo); let exp=format!("<div class=\"footnote-definition\" id=\"z\"><sup class=\"footnote-definition-label\">1</sup>{}</div>",squash(&base)); let got=squash(&h(&inp,fo)); if got!=exp&&f<40{ f+=1; println!("  FN IN {inp:?}\n    {got:?}\n    {exp:?}"); } } println!("fn wrap diffs shown {f}");
}
